# -*- coding: utf-8 -*-
import os

from taf.playwright.core.exceptions import PlaywrightDependencyMissing, UnsupportedBrowser
from taf.playwright.core.utils import to_bool


class BrowserSession(object):
    """Owns one Playwright browser/context/page set."""

    def __init__(self, playwright, browser, context, page, trace_path=None):
        self.playwright = playwright
        self.browser = browser
        self.context = context
        self.page = page
        self.trace_path = trace_path

    def close(self):
        trace_error = None
        if self.trace_path:
            try:
                self.context.tracing.stop(path=self.trace_path)
            except Exception as exc:  # pragma: no cover - best-effort debug artifact
                trace_error = exc
        self.context.close()
        self.browser.close()
        self.playwright.stop()
        if trace_error:
            raise trace_error


class BrowserManager(object):
    """Creates Playwright browser sessions for TAF product libraries."""

    SUPPORTED_BROWSERS = ("chromium", "firefox", "webkit")

    def __init__(self, browser="chromium", headless=True, download_dir=None, trace_dir=None,
                 slow_mo=None, ignore_https_errors=True, viewport=None, proxy=None, channel=None,
                 record_video_dir=None):
        self.browser = str(browser).lower()
        self.headless = to_bool(headless)
        self.download_dir = download_dir
        self.trace_dir = trace_dir
        self.slow_mo = slow_mo
        self.ignore_https_errors = to_bool(ignore_https_errors)
        self.viewport = viewport
        self.proxy = proxy
        self.channel = channel
        self.record_video_dir = record_video_dir

    def create_session(self):
        if self.browser not in self.SUPPORTED_BROWSERS:
            raise UnsupportedBrowser(
                "Unsupported Playwright browser {!r}; expected one of {}".format(
                    self.browser, ", ".join(self.SUPPORTED_BROWSERS)
                )
            )

        try:
            from playwright.sync_api import sync_playwright
        except ImportError:
            raise PlaywrightDependencyMissing(
                "Playwright is not installed. Install it with 'pip install playwright' and run 'playwright install'."
            )

        playwright = sync_playwright().start()
        browser_type = getattr(playwright, self.browser)
        launch_options = {"headless": self.headless}
        if self.slow_mo is not None:
            launch_options["slow_mo"] = int(self.slow_mo)
        if self.download_dir:
            launch_options["downloads_path"] = self.download_dir
        if self.proxy:
            launch_options["proxy"] = self.proxy
        if self.channel and self.browser == "chromium":
            launch_options["channel"] = self.channel

        browser = browser_type.launch(**launch_options)
        context_options = {
            "accept_downloads": True,
            "ignore_https_errors": self.ignore_https_errors,
        }
        if self.viewport:
            context_options["viewport"] = self.viewport
        if self.record_video_dir:
            if not os.path.exists(self.record_video_dir):
                os.makedirs(self.record_video_dir)
            context_options["record_video_dir"] = self.record_video_dir

        context = browser.new_context(**context_options)
        page = context.new_page()

        trace_path = None
        if self.trace_dir:
            if not os.path.exists(self.trace_dir):
                os.makedirs(self.trace_dir)
            trace_path = os.path.join(self.trace_dir, "taf_playwright_trace.zip")
            context.tracing.start(screenshots=True, snapshots=True, sources=True)

        return BrowserSession(playwright, browser, context, page, trace_path)
